import java.util.*;

class Solution {
    private int MOD = 1000000007;
    private int[][][] memo;
    private int[][] apples;
    private int R, C;
    private int solve(int r, int c, int cutsLeft) {
        if (apples[r][c] < cutsLeft + 1) return 0;
        if (cutsLeft == 0) return 1;
        if (memo[r][c][cutsLeft] != -1) return memo[r][c][cutsLeft];
        long ans = 0;
        for (int nr = r + 1; nr < R; nr++) {
            if (apples[r][c] - apples[nr][c] > 0) {
                ans = (ans + solve(nr, c, cutsLeft - 1)) % MOD;
            }
        }
        for (int nc = c + 1; nc < C; nc++) {
            if (apples[r][c] - apples[r][nc] > 0) {
                ans = (ans + solve(r, nc, cutsLeft - 1)) % MOD;
            }
        }
        return memo[r][c][cutsLeft] = (int)ans;
    }
    public int ways(String[] pizza, int k) {
        R = pizza.length; C = pizza[0].length();
        apples = new int[R + 1][C + 1];
        memo = new int[R][C][k];
        for (int[][] row : memo) for (int[] col : row) Arrays.fill(col, -1);
        for (int r = R - 1; r >= 0; r--) {
            for (int c = C - 1; c >= 0; c--) {
                apples[r][c] = (pizza[r].charAt(c) == 'A' ? 1 : 0) + apples[r + 1][c] + apples[r][c + 1] - apples[r + 1][c + 1];
            }
        }
        return solve(0, 0, k - 1);
    }
}

var ways = function(pizza, k) {
    const MOD = 1000000007;
    const R = pizza.length, C = pizza[0].length;
    const apples = Array.from({ length: R + 1 }, () => new Array(C + 1).fill(0));
    for (let r = R - 1; r >= 0; r--) {
        for (let c = C - 1; c >= 0; c--) {
            apples[r][c] = (pizza[r][c] === 'A' ? 1 : 0) + apples[r + 1][c] + apples[r][c + 1] - apples[r + 1][c + 1];
        }
    }
    const memo = new Map();
    const solve = (r, c, cutsLeft) => {
        if (apples[r][c] < cutsLeft + 1) return 0;
        if (cutsLeft === 0) return 1;
        const key = `${r},${c},${cutsLeft}`;
        if (memo.has(key)) return memo.get(key);
        let ans = 0;
        for (let nr = r + 1; nr < R; nr++) {
            if (apples[r][c] - apples[nr][c] > 0) {
                ans = (ans + solve(nr, c, cutsLeft - 1)) % MOD;
            }
        }
        for (let nc = c + 1; nc < C; nc++) {
            if (apples[r][c] - apples[r][nc] > 0) {
                ans = (ans + solve(r, nc, cutsLeft - 1)) % MOD;
            }
        }
        memo.set(key, ans);
        return ans;
    };
    return solve(0, 0, k - 1);
};
